"use client";

import { createContext, useContext, useId, useRef, type HTMLAttributes, type KeyboardEvent, type ReactNode } from "react";

type TabsContextValue = { value: string; onValueChange: (value: string) => void; id: string };
const TabsContext = createContext<TabsContextValue | null>(null);
function useTabs() { const value = useContext(TabsContext); if (!value) throw new Error("Tabs components must be used inside Tabs."); return value; }

export function Tabs({ value, onValueChange, className = "", children, ...props }: HTMLAttributes<HTMLDivElement> & { value: string; onValueChange: (value: string) => void }) {
  const id = useId();
  return <TabsContext.Provider value={{ value, onValueChange, id }}><div className={className} {...props}>{children}</div></TabsContext.Provider>;
}
export function TabsList({ className = "", onKeyDown, ...props }: HTMLAttributes<HTMLDivElement>) {
  const listRef = useRef<HTMLDivElement>(null);
  function move(event: KeyboardEvent<HTMLDivElement>) { if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return; const tabs = [...(listRef.current?.querySelectorAll<HTMLButtonElement>('[role="tab"]') ?? [])]; const current = tabs.indexOf(document.activeElement as HTMLButtonElement); const next = event.key === "Home" ? 0 : event.key === "End" ? tabs.length - 1 : (current + (event.key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length; event.preventDefault(); tabs[next]?.focus(); tabs[next]?.click(); }
  return <div ref={listRef} role="tablist" className={`co-inline-flex co-h-10 co-items-center co-rounded-md co-bg-black/5 co-p-1 ${className}`.trim()} onKeyDown={(event) => { move(event); onKeyDown?.(event); }} {...props} />;
}
export function TabsTrigger({ value, className = "", children, ...props }: HTMLAttributes<HTMLButtonElement> & { value: string; children: ReactNode }) { const tabs = useTabs(); const active = tabs.value === value; return <button type="button" role="tab" id={`${tabs.id}-${value}-tab`} aria-controls={`${tabs.id}-${value}-panel`} aria-selected={active} tabIndex={active ? 0 : -1} className={`co-inline-flex co-h-8 co-items-center co-justify-center co-rounded-sm co-px-3 co-text-sm co-font-medium co-outline-none focus-visible:co-ring-2 ${active ? "co-bg-white co-shadow-sm" : "co-text-black/60"} ${className}`.trim()} onClick={() => tabs.onValueChange(value)} {...props}>{children}</button>; }
export function TabsContent({ value, className = "", ...props }: HTMLAttributes<HTMLDivElement> & { value: string }) { const tabs = useTabs(); if (tabs.value !== value) return null; return <div role="tabpanel" id={`${tabs.id}-${value}-panel`} aria-labelledby={`${tabs.id}-${value}-tab`} tabIndex={0} className={`co-mt-3 co-outline-none focus-visible:co-ring-2 ${className}`.trim()} {...props} />; }
